                        sliprow.ScanningCd = sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["ScanningCd"].ToString();

                        // 数量   ＜売変または廃棄数＞
                        sliprow.DisposalChangeQty = decimal.Parse(sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["DisposalChangeQty"].ToString());

                        // 伝票旧売価
                        sliprow.SlipOldPrice = decimal.Parse(sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["SlipOldPrice"].ToString());

                        // 伝票新売価金額
                        sliprow.SlipNewPrice = decimal.Parse(sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["SlipNewPrice"].ToString());

                        // 伝票廃棄売単価
                        sliprow.SlipDisposalUnitPrica = decimal.Parse(sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["SlipDisposalUnitPrica"].ToString());

                        // 売変区分
                        sliprow.SalesChangeDiv = sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["SalesChangeDiv"].ToString();

                        // 事由
                        sliprow.Reason = sarSlipDetailErrorDataSet.SARSlipDetailError.Rows[i]["Reason"].ToString();
                                                
                        // 8/9 SUEYOSHI 売変金額の合計値の計算式を追加 UPD
                        // 売変金額
                        // sliprow.SalesChangePrice = decimal.Parse(sarSlipDetailDataSet.SARSlipDetail.Rows[i]["SalesChangePrice"].ToString());
                        // （伝票旧売価 - 伝票新売価金額） * 数量
                        sliprow.SalesChangePrice = (sliprow.SlipOldPrice - sliprow.SlipNewPrice) * sliprow.DisposalChangeQty;
                        // 8/9 SUEYOSHI END

                        // 8/15 SUEYOSHI 廃棄金額の合計値の計算式を追加 UPD
                        // 廃棄金額
