        public virtual void SalesChangeDisposalSlipSearchSelectDetail(
            string corporationCD,
            string slipDiv,
            string slipTypeCD,
            string slipNo,
            int slipBranchNo,
            DateTime? disposalChangeDate,
            string storeCD,
            SARSlipDetailDataSet sarSlipDetailDataSet)
        {
            // 概要：検索条件に該当する伝票明細情報を取得する。  

            // 伝票明細一覧情報取得を呼び出し。（DAOCSAR05004）  
            // 法人コード ←引数．法人コード
            // 店舗コード ←引数．店舗コード
            // 伝票種別コード ←引数．伝票種別コード
            // 伝票番号枝番 ←引数．伝票番号枝番
            // 伝票区分 ←引数．伝票区分
            // 伝票番号 ←引数．伝票番号
            // 売変または廃棄日 ←引数．売変または廃棄日
            // ＳＡＲ伝票明細Ds →引数．ＳＡＲ伝票明細Ds
            using (SARSlipDetailTableAdapter sarSlipDetailTableAdapter = new SARSlipDetailTableAdapter())
            {
                sarSlipDetailTableAdapter.FillBySlipDetailListSearchCondition(
                                                corporationCD,
                                                storeCD,
                                                slipTypeCD,
                                                slipBranchNo,
                                                slipDiv,
                                                slipNo,
                                                disposalChangeDate,
                                                sarSlipDetailDataSet);
            }

            if (sarSlipDetailDataSet.SARSlipDetail.Rows.Count.Equals(0))
            {
                // 伝票明細一覧情報Dsが空の場合  
                // 業務エラーをthrowする。【ERRCSARB0167】他のユーザによって変更されている為、  
                // 表示することが出来ませんでした。再検索を行い最新の情報を取得してください。  
                throw RetailBusinessException.CreateInstance(ErrorKey.ERRCSARB0167);
            }
        }
        #endregion

        #region BSCSAR05003000014
