            string corporationCD,
            string inputMediaDiv,
            string inputBatchNo,
            string inputSequenceNo,
            DateTime? inputDate,
            string inputTime,
            string dataType,
            string slipNo,
            string uptakeSequenceNo,
            SARSlipDetailErrorDataSet sarSlipDetailErrorDataSet)
        {
            // 概要：検索条件に該当する伝票明細情報を取得する。 

            // 伝票明細エラー一覧情報取得を呼び出し。（DAOCSAR05005）  
            // 法人コード  ←引数．法人コード 
            // 入力媒体区分 ←引数．入力媒体区分
            // 入力バッチ番号 ←引数．入力バッチ番号
            // 入力ＳＥＱ番号 ←引数．入力ＳＥＱ番号
            // 取込処理日 ←引数．取込処理日
            // 取込処理時刻 ←引数．取込処理時刻
            // データ種別 ←引数．データ種別
            // 取込ＳＥＱ番号 ←引数．取込ＳＥＱ番号
            // ＳＡＲ伝票明細エラーDs →引数．ＳＡＲ伝票明細エラーDs
            using (SARSlipDetailErrorTableAdapter sarSlipDetailErrorTableAdapter = new SARSlipDetailErrorTableAdapter())
            {
                sarSlipDetailErrorTableAdapter.FillBySlipDetailErrorListSearchCondition(
                                                corporationCD,
                                                inputMediaDiv,
                                                inputBatchNo,
                                                inputSequenceNo,
                                                inputDate,
                                                inputTime,
                                                dataType,
                                                uptakeSequenceNo,
                                                sarSlipDetailErrorDataSet);
            }

            if (sarSlipDetailErrorDataSet.SARSlipDetailError.Rows.Count.Equals(0))
            {
                // 伝票明細一覧情報Dsが空の場合 
                // 業務エラーをthrowする。【ERRCSARB0167】他のユーザによって変更されている為、 
