            string corporationCD,
            DateTime? disposalChangeDate,
            SlipDetailListDataSet slipDetailListDataSet)
        {
            // 伝票明細一覧情報Dsを順に読込み以下を行う。
            foreach (SlipDetailListDataSet.SARSlipDetailRow row in slipDetailListDataSet.SARSlipDetail.Rows)
            {
                // 商品検索条件Entity
